CREATE TABLE participant_profiles (user_id TEXT PRIMARY KEY REFERENCES users(id), display_name TEXT NOT NULL, skills TEXT NOT NULL DEFAULT '', completed_at TEXT NOT NULL);
CREATE TABLE portal_roles (user_id TEXT PRIMARY KEY REFERENCES users(id), role TEXT NOT NULL CHECK(role IN ('participant','volunteer','mentor','judge','admin')), granted_by TEXT NOT NULL REFERENCES users(id), updated_at TEXT NOT NULL);
CREATE TABLE team_styles (team_id TEXT PRIMARY KEY REFERENCES teams(id), avatar TEXT NOT NULL DEFAULT 'orbit', palette TEXT NOT NULL DEFAULT 'forest');
CREATE TABLE projects (id TEXT PRIMARY KEY, team_id TEXT NOT NULL UNIQUE REFERENCES teams(id), slug TEXT NOT NULL UNIQUE, draft TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(draft)), revision INTEGER NOT NULL DEFAULT 1, published_version_id TEXT REFERENCES submission_versions(id), updated_at TEXT NOT NULL);
CREATE TABLE project_upvotes (project_id TEXT NOT NULL REFERENCES projects(id), user_id TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL, PRIMARY KEY(project_id,user_id));
CREATE TABLE project_comments (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), author_id TEXT NOT NULL REFERENCES users(id), body TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE INDEX project_comments_project ON project_comments(project_id,created_at);
CREATE TABLE project_assignments (project_id TEXT NOT NULL REFERENCES projects(id), user_id TEXT NOT NULL REFERENCES users(id), kind TEXT NOT NULL CHECK(kind IN ('judge','mentor')), PRIMARY KEY(project_id,user_id));
CREATE TABLE project_review_history (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), version_id TEXT NOT NULL REFERENCES submission_versions(id), author_id TEXT NOT NULL REFERENCES users(id), kind TEXT NOT NULL CHECK(kind IN ('judge','mentor','admin')), body TEXT NOT NULL, rating REAL CHECK(rating BETWEEN 0 AND 10), created_at TEXT NOT NULL);
CREATE TABLE evaluation_runs (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), version_id TEXT NOT NULL REFERENCES submission_versions(id), config_key TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN ('queued','running','completed','failed','stale')), report TEXT CHECK(report IS NULL OR json_valid(report)), error TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE UNIQUE INDEX evaluation_single_active ON evaluation_runs(version_id,config_key) WHERE state IN ('queued','running');
CREATE TRIGGER project_review_immutable BEFORE UPDATE ON project_review_history BEGIN SELECT RAISE(ABORT,'IMMUTABLE'); END;
CREATE TRIGGER project_review_no_delete BEFORE DELETE ON project_review_history BEGIN SELECT RAISE(ABORT,'IMMUTABLE'); END;
CREATE TRIGGER project_publication_version BEFORE UPDATE OF published_version_id ON projects WHEN NEW.published_version_id IS NOT NULL BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM submission_versions WHERE id=NEW.published_version_id AND team_id=NEW.team_id) THEN RAISE(ABORT,'PROJECT_VERSION_MISMATCH') END; END;
DROP TRIGGER membership_guard;
CREATE TRIGGER membership_guard BEFORE INSERT ON memberships BEGIN
 SELECT CASE WHEN (SELECT count(*) FROM memberships WHERE team_id=NEW.team_id)>=5 THEN RAISE(ABORT,'TEAM_FULL') END;
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM users u LEFT JOIN registrations r ON r.email=u.email WHERE u.id=NEW.user_id AND COALESCE(r.status,'pending') NOT IN ('rejected','cancelled')) THEN RAISE(ABORT,'REGISTRATION_REQUIRED') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM event_settings WHERE id=1 AND active=1 AND NEW.joined_at >= json_extract(policy,'$.membershipFreeze')) THEN RAISE(ABORT,'MEMBERSHIP_FROZEN') END;
END;
CREATE TABLE event_content (id INTEGER PRIMARY KEY, draft TEXT NOT NULL, published TEXT, revision INTEGER NOT NULL DEFAULT 1, updated_at TEXT NOT NULL);
CREATE TABLE private_venue (id INTEGER PRIMARY KEY, draft TEXT NOT NULL, published TEXT, revision INTEGER NOT NULL DEFAULT 1, updated_at TEXT NOT NULL);
CREATE TABLE private_venue_managers (user_id TEXT PRIMARY KEY REFERENCES users(id), granted_by TEXT NOT NULL REFERENCES users(id), updated_at TEXT NOT NULL);
CREATE TABLE event_content_history (id TEXT PRIMARY KEY, scope TEXT NOT NULL CHECK(scope IN ('public','private')), revision INTEGER NOT NULL, snapshot TEXT NOT NULL, actor_id TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL);
CREATE TABLE write_guards (token TEXT PRIMARY KEY, valid INTEGER NOT NULL CHECK(valid=1));
CREATE TABLE project_eligibility (project_id TEXT PRIMARY KEY REFERENCES projects(id), version_id TEXT NOT NULL REFERENCES submission_versions(id), status TEXT NOT NULL CHECK(status IN ('eligible','ineligible','needs_review')), reason TEXT NOT NULL, decided_by TEXT NOT NULL REFERENCES users(id), updated_at TEXT NOT NULL);
CREATE TRIGGER revised_revision_project_review_history_insert AFTER INSERT ON project_review_history BEGIN UPDATE scoring_revision SET version=version+1 WHERE id=1; END;
CREATE TRIGGER revised_frozen_project_review_history_insert BEFORE INSERT ON project_review_history WHEN EXISTS(SELECT 1 FROM result_snapshots) BEGIN SELECT RAISE(ABORT,'RESULTS_FROZEN'); END;
CREATE TRIGGER revised_revision_project_review_history_update AFTER UPDATE ON project_review_history BEGIN UPDATE scoring_revision SET version=version+1 WHERE id=1; END;
CREATE TRIGGER revised_frozen_project_review_history_update BEFORE UPDATE ON project_review_history WHEN EXISTS(SELECT 1 FROM result_snapshots) BEGIN SELECT RAISE(ABORT,'RESULTS_FROZEN'); END;
CREATE TRIGGER revised_revision_project_review_history_delete AFTER DELETE ON project_review_history BEGIN UPDATE scoring_revision SET version=version+1 WHERE id=1; END;
CREATE TRIGGER revised_frozen_project_review_history_delete BEFORE DELETE ON project_review_history WHEN EXISTS(SELECT 1 FROM result_snapshots) BEGIN SELECT RAISE(ABORT,'RESULTS_FROZEN'); END;
CREATE TRIGGER revised_revision_project_assignments_insert AFTER INSERT ON project_assignments BEGIN UPDATE scoring_revision SET version=version+1 WHERE id=1; END;
CREATE TRIGGER revised_revision_project_assignments_update AFTER UPDATE ON project_assignments BEGIN UPDATE scoring_revision SET version=version+1 WHERE id=1; END;
CREATE TRIGGER revised_revision_project_assignments_delete AFTER DELETE ON project_assignments BEGIN UPDATE scoring_revision SET version=version+1 WHERE id=1; END;
CREATE TRIGGER revised_revision_project_eligibility_insert AFTER INSERT ON project_eligibility BEGIN UPDATE scoring_revision SET version=version+1 WHERE id=1; END;
CREATE TRIGGER revised_frozen_project_eligibility_insert BEFORE INSERT ON project_eligibility WHEN EXISTS(SELECT 1 FROM result_snapshots) BEGIN SELECT RAISE(ABORT,'RESULTS_FROZEN'); END;
CREATE TRIGGER revised_revision_project_eligibility_update AFTER UPDATE ON project_eligibility BEGIN UPDATE scoring_revision SET version=version+1 WHERE id=1; END;
CREATE TRIGGER revised_frozen_project_eligibility_update BEFORE UPDATE ON project_eligibility WHEN EXISTS(SELECT 1 FROM result_snapshots) BEGIN SELECT RAISE(ABORT,'RESULTS_FROZEN'); END;
CREATE TRIGGER revised_revision_project_eligibility_delete AFTER DELETE ON project_eligibility BEGIN UPDATE scoring_revision SET version=version+1 WHERE id=1; END;
CREATE TRIGGER revised_frozen_project_eligibility_delete BEFORE DELETE ON project_eligibility WHEN EXISTS(SELECT 1 FROM result_snapshots) BEGIN SELECT RAISE(ABORT,'RESULTS_FROZEN'); END;
CREATE TRIGGER revised_revision_portal_roles_insert AFTER INSERT ON portal_roles BEGIN UPDATE scoring_revision SET version=version+1 WHERE id=1; END;
CREATE TRIGGER revised_revision_portal_roles_update AFTER UPDATE ON portal_roles BEGIN UPDATE scoring_revision SET version=version+1 WHERE id=1; END;
CREATE TRIGGER revised_revision_portal_roles_delete AFTER DELETE ON portal_roles BEGIN UPDATE scoring_revision SET version=version+1 WHERE id=1; END;
CREATE TRIGGER revised_revision_project_upvotes_insert AFTER INSERT ON project_upvotes BEGIN UPDATE scoring_revision SET version=version+1 WHERE id=1; END;
CREATE TRIGGER revised_revision_project_upvotes_update AFTER UPDATE ON project_upvotes BEGIN UPDATE scoring_revision SET version=version+1 WHERE id=1; END;
CREATE TRIGGER revised_revision_project_upvotes_delete AFTER DELETE ON project_upvotes BEGIN UPDATE scoring_revision SET version=version+1 WHERE id=1; END;
CREATE TRIGGER revised_revision_project_comments_insert AFTER INSERT ON project_comments BEGIN UPDATE scoring_revision SET version=version+1 WHERE id=1; END;
CREATE TRIGGER revised_revision_project_comments_update AFTER UPDATE ON project_comments BEGIN UPDATE scoring_revision SET version=version+1 WHERE id=1; END;
CREATE TRIGGER revised_revision_project_comments_delete AFTER DELETE ON project_comments BEGIN UPDATE scoring_revision SET version=version+1 WHERE id=1; END;
